use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

struct Node;

/// Key in the shared store under which every call records the input it received.
const LAST_INPUT_KEY: &str = "last-input";

/// How many times to offer the notification before giving up.
const NOTIFY_ATTEMPTS: u32 = 3;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Record the input received on this call. This is a side effect only;
        // it does not change the output.
        state_rw::put(LAST_INPUT_KEY, &feed_url);

        // Read the time.
        let now = wall_clock::now();
        let seconds = now.seconds;

        // The one permitted fetch. A transport failure is a value, so a feed
        // that is down counts as zero characters fetched. A URL outside the
        // allowlist traps at the boundary, by design.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Notify the digest channel.
        let message = format!(
            "heartbeat: t={}s fetched {} chars from {}",
            seconds, fetched, feed_url
        );

        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }

        // The contract requires `notified == true`. If the channel refused
        // every attempt, trap instead of returning a report that breaks
        // the contract or claims a delivery that did not happen.
        if !notified {
            panic!("notifier refused the heartbeat notification");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
